package ai.interviewhq.api.question.repository;
import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.jupiter.api.Test; import software.amazon.awssdk.services.dynamodb.DynamoDbClient; import software.amazon.awssdk.services.dynamodb.model.*; import java.util.Map; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class DynamoDbQuestionRepositoryTest {
 @Test void detailUsesIdLookupThenCanonicalItem(){DynamoDbClient c=mock(DynamoDbClient.class);when(c.getItem(any(GetItemRequest.class))).thenReturn(GetItemResponse.builder().item(Map.of("data",AttributeValue.builder().m(Map.of("experienceId",AttributeValue.builder().n("4").build(),"dedupeHash",AttributeValue.builder().s("abc").build())).build())).build()).thenReturn(GetItemResponse.builder().item(Map.of("data",AttributeValue.builder().m(Map.of("id",AttributeValue.builder().n("7").build(),"questionText",AttributeValue.builder().s("Q").build())).build())).build());var r=new DynamoDbQuestionRepository(c,new ObjectMapper(),"table").findById(7);assertTrue(r.found());assertEquals("Q",r.data().get("questionText"));var captor=org.mockito.ArgumentCaptor.forClass(GetItemRequest.class);verify(c,times(2)).getItem(captor.capture());assertEquals("QUESTION_ID#7",captor.getAllValues().get(0).key().get("pk").s());assertEquals("EXPERIENCE#4",captor.getAllValues().get(1).key().get("pk").s());}
 @Test void experienceListUsesQueryNotScan(){DynamoDbClient c=mock(DynamoDbClient.class);when(c.query(any(QueryRequest.class))).thenReturn(QueryResponse.builder().items(java.util.List.of()).build());var r=new DynamoDbQuestionRepository(c,new ObjectMapper(),"table");r.listByExperience(4,25,Map.of());var captor=org.mockito.ArgumentCaptor.forClass(QueryRequest.class);verify(c).query(captor.capture());assertTrue(captor.getValue().keyConditionExpression().contains("begins_with"));verify(c,never()).scan(any(ScanRequest.class));}
}